// AG Grid v36. CSV export is Community; Excel export (ExcelExportModule) is Enterprise.
import { useMemo, useRef } from "react";
import { AgGridProvider, AgGridReact } from "ag-grid-react";
import { ClientSideRowModelModule, CsvExportModule } from "ag-grid-community";
import type { ColDef, ExcelStyle } from "ag-grid-community";
import { ContextMenuModule, ExcelExportModule } from "ag-grid-enterprise";

const modules = [ClientSideRowModelModule, CsvExportModule, ExcelExportModule, ContextMenuModule];

interface Sale { region: string; product: string; orderDate: string; revenue: number }

export function SalesReport({ rows }: { rows: Sale[] }) {
  const gridRef = useRef<AgGridReact<Sale>>(null);

  const columnDefs = useMemo<ColDef<Sale>[]>(() => [
    { field: "region" },
    { field: "product" },
    // ISO strings (`yyyy-mm-ddThh:mm:ss`) export as Excel dates via the DateTime data type
    { field: "orderDate", cellClass: "isoDate" },
    { field: "revenue", cellClass: "currency" },
  ], []);

  // Excel Styles are matched to columns by cellClass id
  const excelStyles = useMemo<ExcelStyle[]>(() => [
    { id: "header", font: { bold: true } },
    { id: "isoDate", dataType: "DateTime", numberFormat: { format: "dd/mm/yyyy" } },
    { id: "currency", numberFormat: { format: "£#,##0.00" } },
  ], []);

  return (
    <AgGridProvider modules={modules}>
      <button onClick={() => gridRef.current?.api.exportDataAsExcel({ fileName: "sales.xlsx", sheetName: "Sales" })}>
        Export to Excel
      </button>
      <button onClick={() => gridRef.current?.api.exportDataAsCsv({ fileName: "sales.csv" })}>
        Export to CSV
      </button>
      <div style={{ height: 500 }}>
        <AgGridReact<Sale>
          ref={gridRef}
          rowData={rows}
          columnDefs={columnDefs}
          excelStyles={excelStyles}
        />
      </div>
    </AgGridProvider>
  );
}
